    plan_uuid := (plan_item->>'plan_id')::uuid;

    PERFORM 1
    FROM public.devotional_plans
    WHERE id = plan_uuid
      AND source_url IS NOT DISTINCT FROM plan_item->>'source_url'
      AND total_days = (plan_item->>'total_days')::integer
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Waves 42-48 preflight: plan %, source, or day count mismatch', plan_uuid;
    END IF;

    SELECT count(*), count(DISTINCT day_number), min(day_number), max(day_number)
    INTO actual_count, distinct_count, min_day, max_day
    FROM public.devotional_days
    WHERE plan_id = plan_uuid;
    IF actual_count <> (plan_item->>'total_days')::integer
       OR distinct_count <> (plan_item->>'total_days')::integer
       OR min_day <> 1
       OR max_day <> (plan_item->>'total_days')::integer THEN
      RAISE EXCEPTION 'Waves 42-48 preflight: plan % does not have a contiguous day sequence', plan_uuid;
    END IF;

    IF jsonb_array_length(plan_item->'days') <> (plan_item->>'total_days')::integer
       OR (SELECT count(DISTINCT (value->>'day_number')::integer)
           FROM jsonb_array_elements(plan_item->'days'))
          <> (plan_item->>'total_days')::integer
       OR (SELECT min((value->>'day_number')::integer)
           FROM jsonb_array_elements(plan_item->'days')) <> 1
       OR (SELECT max((value->>'day_number')::integer)
           FROM jsonb_array_elements(plan_item->'days'))
          <> (plan_item->>'total_days')::integer THEN
      RAISE EXCEPTION 'Waves 42-48 payload: plan % has an incomplete day payload', plan_uuid;
    END IF;

    FOR day_item IN
      SELECT value
      FROM jsonb_array_elements(plan_item->'days')
      ORDER BY (value->>'day_number')::integer
    LOOP
      SELECT id INTO STRICT day_uuid
      FROM public.devotional_days
      WHERE plan_id = plan_uuid
        AND day_number = (day_item->>'day_number')::integer
      FOR UPDATE;

      UPDATE public.devotional_days
      SET title = day_item->>'title',
          content = day_item->>'content',
          updated_at = now()
      WHERE id = day_uuid;

      SELECT array_agg(value ORDER BY ordinality)
      INTO expected_references
      FROM jsonb_array_elements_text(day_item->'references')
           WITH ORDINALITY AS reference_item(value, ordinality);
      IF coalesce(array_length(expected_references, 1), 0) = 0 THEN
        RAISE EXCEPTION 'Waves 42-48 payload: plan %, day % has no Scripture references',
          plan_uuid, day_item->>'day_number';
      END IF;

      UPDATE public.scripture_references
      SET reference = expected_references,
          updated_at = now()
      WHERE day_id = day_uuid AND user_id IS NULL;
      IF NOT FOUND THEN
        INSERT INTO public.scripture_references
          (user_id, day_id, reference, created_at, updated_at)
        VALUES (NULL, day_uuid, expected_references, now(), now());
      END IF;

      SELECT count(*) INTO actual_count
      FROM public.scripture_references
      WHERE day_id = day_uuid
        AND user_id IS NULL
        AND reference = expected_references;
      IF actual_count <> 1 THEN
        RAISE EXCEPTION 'Waves 42-48 postflight: plan %, day % has a reference mismatch',
          plan_uuid, day_item->>'day_number';
      END IF;
    END LOOP;

    UPDATE public.devotional_plans
    SET title = plan_item->>'title',
        description = plan_item->>'description',
        status = 'published',
        updated_at = now()
    WHERE id = plan_uuid;

    IF NOT EXISTS (
      SELECT 1 FROM public.devotional_plans
      WHERE id = plan_uuid
        AND title = plan_item->>'title'
        AND description = plan_item->>'description'
        AND status = 'published'
    ) THEN
      RAISE EXCEPTION 'Waves 42-48 postflight: plan % publication mismatch', plan_uuid;
    END IF;
  END LOOP;
END
$apply_waves42_48$;

COMMIT;
